'use client'

import {
  Box,
  Flex,
  Text,
  IconButton,
  Button,
  Stack,
//   Collapse,
  Icon,
  Popover,
  PopoverTrigger,
  PopoverContent,
  useBreakpointValue,
  useDisclosure,
  Container,
  HStack,
} from '@chakra-ui/react'
import {
  HamburgerIcon,
  CloseIcon,
  ChevronDownIcon,
  ChevronRightIcon,
} from '@chakra-ui/icons'
import { Logo } from '../logo';

export const Header = () => {
  return (
    <Box bg={"white"} minH={"10"} maxH={"10"} w={"full"} position={"fixed"}>
      <Container>
        <Flex justify="space-between" align="center">
          <Box  position={"relative"} display={"inline-block"}>
            <Box position={"absolute"} zIndex={"max"} display={"block"} h={"2xs"} w={"2xs"}><Logo/></Box>
          </Box>
          <HStack>
            <Box>Link 1</Box>
            <Box>Link 2</Box>
            <Box>Link 3</Box>
          </HStack>
          <Box>Sign In</Box>
        </Flex>
      </Container>
    </Box>
  );
}
